using System.Threading.Channels;
using System.Threading.Tasks;

namespace Bench
{
    public class Program
    {
        /// <summary>

golden_completion:
/// Creates a bounded Channel&lt;int&gt; with capacity 2 using
/// Channel.CreateBounded with BoundedChannelFullMode.Wait.
/// The producer calls WriteAsync to enqueue values, blocking when
/// the channel is full. The consumer calls ReadAsync in a loop
/// until TryRead returns false after the writer calls Complete().
/// Returns the sum of all consumed values.
/// </summary>

suffix:
        public static async Task<int> ProduceConsumeAsync(int[] values)
        {
            var ch = Channel.CreateBounded<int>(new BoundedChannelOptions(2)
            {
                FullMode = BoundedChannelFullMode.Wait
            });

            var producer = Task.Run(async () =>
            {
                foreach (var v in values)
                    await ch.Writer.WriteAsync(v);
                ch.Writer.Complete();
            });

            int sum = 0;
            await foreach (var item in ch.Reader.ReadAllAsync())
                sum += item;

            await producer;
            return sum;
        }

        static async Task Main()
        {
            int result = await ProduceConsumeAsync(new[] { 1, 2, 3, 4, 5 });
            if (!(result == 15)) throw new Exception($"expected 15 got {result}");
            int empty = await ProduceConsumeAsync(Array.Empty<int>());
            if (!(empty == 0)) throw new Exception("empty should be 0");
        }
    }
}

