        public static DateTime ParseRomanianDate(string s)
        {
            var ci = new CultureInfo("en-US");
            var dtfi = ci.DateTimeFormat;
            dtfi.AbbreviatedMonthNames = new[]
            {
                "Ian", "Fev", "Mrt", "Avr", "Mai", "Iun",
                "Iul", "Avg", "Sep", "Okt", "Noe", "Dek", ""
            };
            dtfi.AbbreviatedMonthGenitiveNames = new[]
            {
                "Ian", "Fev", "Mrt", "Avr", "Mai", "Iun",
                "Iul", "Avg", "Sep", "Okt", "Noe", "Dek", ""
            };
            dtfi.MonthNames = new[]
            {
                "Ianuarie", "Februarie", "Martie", "Aprilie", "Maie", "Iunie",
                "Iulie", "August", "Septembrie", "Octombrie", "Noiembrie", "Decembrie", ""
            };
            dtfi.MonthGenitiveNames = new[]
            {
                "Ianuarie", "Februarie", "Martie", "Aprilie", "Maie", "Iunie",
                "Iulie", "August", "Septembrie", "Octombrie", "Noiembrie", "Decembrie", ""
            };
            dtfi.DateSeparator = ".";
            return DateTime.ParseExact(s, "dd.MMM.yyyy", ci);
        }

        static void Main()
        {
            var d1 = ParseRomanianDate("15.Ian.2024");
            if (!(d1.Month == 1 && d1.Day == 15 && d1.Year == 2024)) throw new Exception("d1");
            var d2 = ParseRomanianDate("01.Dek.1999");
            if (!(d2.Month == 12 && d2.Day == 1 && d2.Year == 1999)) throw new Exception("d2");
            var d3 = ParseRomanianDate("28.Fev.2000");
            if (!(d3.Month == 2 && d3.Day == 28 && d3.Year == 2000)) throw new Exception("d3");
            Console.WriteLine("Romanian dates OK");
        }
    }
}

